CREATE TABLE IF NOT EXISTS schema_versions(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, entity_id TEXT NOT NULL, at TEXT NOT NULL, payload TEXT NOT NULL, previous_hash TEXT NOT NULL, hash TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS events_no_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT,'Append-only events'); END;
CREATE TRIGGER IF NOT EXISTS events_no_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT,'Append-only events'); END;
CREATE TABLE IF NOT EXISTS signals(id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL UNIQUE, symbol TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, payload TEXT NOT NULL, chart_path TEXT);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY, signal_id TEXT NOT NULL UNIQUE REFERENCES signals(id), status TEXT NOT NULL, created_at TEXT NOT NULL, risk REAL NOT NULL CHECK(risk>=0), volume REAL NOT NULL CHECK(volume>0), broker_id TEXT, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS positions(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), symbol TEXT NOT NULL, status TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fills(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), at TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS fills_no_update BEFORE UPDATE ON fills BEGIN SELECT RAISE(ABORT,'Append-only fills'); END;
CREATE TRIGGER IF NOT EXISTS fills_no_delete BEFORE DELETE ON fills BEGIN SELECT RAISE(ABORT,'Append-only fills'); END;
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY, event_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, available_at TEXT NOT NULL, payload TEXT NOT NULL, remote_id TEXT, error TEXT);
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY, kind TEXT NOT NULL, start_at TEXT NOT NULL, end_at TEXT NOT NULL, payload TEXT NOT NULL, UNIQUE(kind,start_at,end_at));
CREATE TRIGGER IF NOT EXISTS reports_no_update BEFORE UPDATE ON reports BEGIN SELECT RAISE(ABORT,'Append-only reports'); END;
CREATE TRIGGER IF NOT EXISTS reports_no_delete BEFORE DELETE ON reports BEGIN SELECT RAISE(ABORT,'Append-only reports'); END;
CREATE TABLE IF NOT EXISTS state(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bars(symbol TEXT NOT NULL, timeframe TEXT NOT NULL, time TEXT NOT NULL, source TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(symbol,timeframe,time,source));
CREATE TABLE IF NOT EXISTS research(id TEXT PRIMARY KEY, created_at TEXT NOT NULL, kind TEXT NOT NULL, policy_hash TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS research_no_update BEFORE UPDATE ON research BEGIN SELECT RAISE(ABORT,'Append-only research'); END;
CREATE TRIGGER IF NOT EXISTS research_no_delete BEFORE DELETE ON research BEGIN SELECT RAISE(ABORT,'Append-only research'); END;
CREATE INDEX IF NOT EXISTS events_entity ON events(entity_id,seq);
CREATE INDEX IF NOT EXISTS outbox_due ON outbox(status,available_at);
CREATE INDEX IF NOT EXISTS fills_time ON fills(at);
